from __future__ import annotations; import textwrap; from pathlib import Path; import pytest; from common.meta.extension import check_authority_reconcile as g_reconcile; from common.meta.extension import check_draft_packages as g_draft; from common.meta.extension import check_tier_ast_literal as g_tier
def _write_contract(repo: Path, name: str, body: str) -> None: pkg = repo / 'common' / name; pkg.mkdir(parents=True, exist_ok=True); (pkg / 'contract.py').write_text(textwrap.dedent(body), encoding='utf-8')
_active = lambda name, *, tier='"CODE-ONLY"', roadmap='': f'\n    from common.meta.package_contract import PackageContract, ACRecord\n    CONTRACT = PackageContract(\n        name="{name}", klass="infra", status="active", tier={tier},\n        depends_on=[], interface=[], events=[], invariants=[], roadmap=[{roadmap}])\n    '
def test_1b_passes_for_literal_tier(tmp_path: Path) -> None:
    _write_contract(tmp_path, 'good', _active('good')); assert g_tier.violations(tmp_path) == []; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); _write_contract(_m1_tmp, 'bad', '\n        from common.meta.package_contract import PackageContract\n        T = "CODE-ONLY"\n        CONTRACT = PackageContract(\n            name="bad", klass="infra", status="active", tier=T,\n            depends_on=[], interface=[], events=[], invariants=[], roadmap=[])\n        '); _m1_errors = g_tier.violations(_m1_tmp); assert len(_m1_errors) == 1 and 'AST-readable literal' in _m1_errors[0]; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); _write_contract(_m2_tmp, 'wip', '\n        from common.meta.package_contract import PackageContract\n        CONTRACT = PackageContract(\n            name="wip", klass="infra", status="draft",\n            depends_on=[], interface=[], events=[], invariants=[], roadmap=[])\n        '); assert g_tier.violations(_m2_tmp) == []; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); _write_contract(_m3_tmp, 'wip', '\n        from common.meta.package_contract import PackageContract, ACRecord\n        CONTRACT = PackageContract(\n            name="wip", klass="infra", status="draft",\n            depends_on=[], interface=[], events=[], invariants=[], roadmap=[\n            ACRecord(id="AC-wip.1.1", statement="s", test="t::f",\n                     priority="P0", status="done")])\n        '); _m3_baseline = _m3_tmp / 'bl.json'; _m3_baseline.write_text('{"draft_packages": ["wip"]}', encoding='utf-8'); _m3_errors = g_draft.violations(_m3_tmp, _m3_baseline); assert any(('done AC' in _m3_e for _m3_e in _m3_errors)); _m4_tmp = tmp_path / '_m4'; _m4_tmp.mkdir(exist_ok=True); _write_contract(_m4_tmp, 'wip', '\n        from common.meta.package_contract import PackageContract\n        CONTRACT = PackageContract(\n            name="wip", klass="infra", status="draft",\n            depends_on=[], interface=[], events=[], invariants=[], roadmap=[])\n        '); _m4_baseline = _m4_tmp / 'bl.json'; _m4_baseline.write_text('{"draft_packages": []}', encoding='utf-8'); _m4_errors = g_draft.violations(_m4_tmp, _m4_baseline); assert any(('not registered' in _m4_e for _m4_e in _m4_errors)); _m5_tmp = tmp_path / '_m5'; _m5_tmp.mkdir(exist_ok=True); _write_contract(_m5_tmp, 'wip', '\n        from common.meta.package_contract import PackageContract, ACRecord\n        S = "done"\n        CONTRACT = PackageContract(\n            name="wip", klass="infra", status="draft",\n            depends_on=[], interface=[], events=[], invariants=[], roadmap=[\n            ACRecord(id="AC-wip.1.1", statement="s", test="t::f",\n                     priority="P0", status=S)])\n        '); _m5_baseline = _m5_tmp / 'bl.json'; _m5_baseline.write_text('{"draft_packages": ["wip"]}', encoding='utf-8'); _m5_errors = g_draft.violations(_m5_tmp, _m5_baseline); assert any(('not an AST-readable literal' in _m5_e for _m5_e in _m5_errors)); _m6_tmp = tmp_path / '_m6'; _m6_tmp.mkdir(exist_ok=True); _m6_bad = _m6_tmp / 'bl.json'; _m6_bad.write_text('["wip"]', encoding='utf-8')
    with pytest.raises(ValueError): g_draft.load_baseline(_m6_bad)
_ac_pointing_at = lambda test_file: f'ACRecord(id="AC-p.1.1", statement="s", test="{test_file}::t", priority="P0", status="done"),'
def test_reconcile_flags_llm_test_under_code_only(tmp_path: Path) -> None: (tmp_path / 'cass_test.py').write_text('def t():\n    cassette.replay()  # cassette marker\n', encoding='utf-8'); _write_contract(tmp_path, 'p', _active('p', tier='"CODE-ONLY"', roadmap=_ac_pointing_at('cass_test.py'))); violations, _ = g_reconcile.reconcile(tmp_path); assert any(('declared CODE-ONLY but' in v for v in violations)); _m7_tmp = tmp_path / '_m7'; _m7_tmp.mkdir(exist_ok=True); (_m7_tmp / 'det_test.py').write_text('def t():\n    assert 1 == 1\n', encoding='utf-8'); _write_contract(_m7_tmp, 'p', _active('p', tier='"CODE-ONLY"', roadmap=_ac_pointing_at('det_test.py'))); _m7_violations, _m7__ = g_reconcile.reconcile(_m7_tmp); assert _m7_violations == []; _m8_tmp = tmp_path / '_m8'; _m8_tmp.mkdir(exist_ok=True); (_m8_tmp / 'det_test.py').write_text('def t():\n    assert 1 == 1\n', encoding='utf-8'); _write_contract(_m8_tmp, 'p', _active('p', tier='"LLM-ONLY"', roadmap=_ac_pointing_at('det_test.py'))); _m8_violations, _m8__ = g_reconcile.reconcile(_m8_tmp); assert any(('declared LLM-ONLY but' in _m8_v for _m8_v in _m8_violations)); _m9_tmp = tmp_path / '_m9'; _m9_tmp.mkdir(exist_ok=True); _write_contract(_m9_tmp, 'wip', '\n        from common.meta.package_contract import PackageContract, ACRecord\n        CONTRACT = PackageContract(\n            name="wip", klass="infra", status="draft",\n            depends_on=[], interface=[], events=[], invariants=[], roadmap=[\n            ACRecord(id="AC-wip.1.1", statement="s", test="t::f",\n                     priority="P0", status="open")])\n        '); _m9_baseline = _m9_tmp / 'bl.json'; _m9_baseline.write_text('{"draft_packages": ["wip"]}', encoding='utf-8')
